    # ── ③ 직사각형과 정사각형의 넓이 ──
    def r_rect(qid, diff, a, c, fig=False, word=None, unit='cm'):
        ans = a * c
        t = word or ((f'[[fig:shp:rect:{a}:{c}:{unit}]] ' if fig else '') + f'가로 {a} {unit}, 세로 {c} {unit}인 직사각형의 넓이는 몇 {unit}²일까요?')
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(2 * (a + c), unit + '²'), 'perim'), (U(a + c, unit + '²'), 'add'), (U(ans // 2, unit + '²') if ans % 2 == 0 else None, 'tri'), (U(ans + a, unit + '²'), 'calc')],
                 H_R, f'가로 {a} × 세로 {c}', f'{a} × {c} = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 직사각형의 넓이를 구하는 식을 세워요')
    def r_sq(qid, diff, s, fig=False, unit='cm'):
        ans = s * s
        t = (f'[[fig:shp:sq:{s}:{unit}]] ' if fig else '') + f'한 변의 길이가 {s} {unit}인 정사각형의 넓이는 몇 {unit}²일까요?'
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(4 * s, unit + '²'), 'perim'), (U(2 * s, unit + '²'), 'add'), (U(ans // 2, unit + '²') if ans % 2 == 0 else None, 'tri'), (U(ans + s, unit + '²'), 'calc')],
                 H_R, f'한 변 {s} × 한 변 {s}', f'{s} × {s} = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 정사각형의 넓이를 구하는 식을 세워요')

