    # ── ④ 평행사변형과 삼각형의 넓이 ──
    def pa(qid, diff, a, h, s, fig=True, unit='cm'):
        ans = a * h
        t = (f'[[fig:shp:par:{a}:{h}:{s}:{unit}]] 평행사변형의 넓이는 몇 {unit}²일까요?' if fig else f'밑변이 {a} {unit}, 높이가 {h} {unit}인 평행사변형의 넓이는 몇 {unit}²일까요?')
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(a * s, unit + '²'), 'side') if s else None, (U(ans // 2, unit + '²') if ans % 2 == 0 else None, 'tri'), (U(2 * (a + s), unit + '²') if s else U(2 * (a + h), unit + '²'), 'perim'), (U(a + h, unit + '²'), 'add')],
                 H_PT, f'높이는 밑변과 수직인 선분이에요. 밑변 {a} × 높이 {h}', f'{a} × {h} = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 밑변과 높이가 어느 것인지 찾아요')
    def tr(qid, diff, a, h, fig=True, word=None, unit='cm'):
        ans2 = a * h; assert ans2 % 2 == 0; ans = ans2 // 2
        t = word or ((f'[[fig:shp:tri:{a}:{h}:{unit}]] 삼각형의 넓이는 몇 {unit}²일까요?') if fig else f'밑변이 {a} {unit}, 높이가 {h} {unit}인 삼각형의 넓이는 몇 {unit}²일까요?')
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(ans2, unit + '²'), 'nohalf'), (U(a + h, unit + '²'), 'add'), (U(ans // 2, unit + '²') if ans % 2 == 0 else U(ans + h, unit + '²'), 'calc')],
                 H_PT, f'밑변 {a} × 높이 {h} ÷ 2', f'{a} × {h} ÷ 2 = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 삼각형의 넓이를 구하는 식을 세워요')

