    # ── ⑤ 사다리꼴과 마름모의 넓이 ──
    def tz(qid, diff, a, c, h, fig=True, word=None, unit='cm'):
        s2 = (a + c) * h; assert s2 % 2 == 0; ans = s2 // 2
        t = word or ((f'[[fig:shp:trap:{a}:{c}:{h}:{unit}]] 사다리꼴의 넓이는 몇 {unit}²일까요?') if fig else f'윗변이 {a} {unit}, 아랫변이 {c} {unit}, 높이가 {h} {unit}인 사다리꼴의 넓이는 몇 {unit}²일까요?')
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(s2, unit + '²'), 'nohalf'), (U(c * h, unit + '²'), 'one'), (U(a * c * h // 2, unit + '²') if (a * c * h) % 2 == 0 else U(a * c * h, unit + '²'), 'guess'), (U(a + c + h, unit + '²'), 'add')],
                 H_TR, f'(윗변 {a} + 아랫변 {c}) × 높이 {h} ÷ 2', f'({a} + {c}) × {h} ÷ 2 = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 윗변과 아랫변을 먼저 더해요')
    def rh(qid, diff, d1, d2, fig=True, word=None, unit='cm'):
        s2 = d1 * d2; assert s2 % 2 == 0; ans = s2 // 2
        t = word or ((f'[[fig:shp:rhom:{d1}:{d2}:{unit}]] 마름모의 넓이는 몇 {unit}²일까요?') if fig else f'두 대각선의 길이가 {d1} {unit}, {d2} {unit}인 마름모의 넓이는 몇 {unit}²일까요?')
        return Q(b, qid, diff, t, U(ans, unit + '²'), [(U(s2, unit + '²'), 'nohalf'), (U(d1 + d2, unit + '²'), 'add'), (U(ans // 2, unit + '²') if ans % 2 == 0 else U(ans + d1, unit + '²'), 'calc'), (U(2 * (d1 + d2), unit + '²'), 'perim')],
                 H_TR, f'한 대각선 {d1} × 다른 대각선 {d2} ÷ 2', f'{d1} × {d2} ÷ 2 = {ans} → 답은 {ieyo(U(ans, unit + "²"))}.', '첫 단계: 두 대각선의 길이를 확인해요')

